// src/core/health/health.module.ts
import { FastifyPluginAsync } from 'fastify';
import { pool } from '@core/database/pool';
import { readFileSync } from 'fs';
import { join } from 'path';

const packageJsonPath = join(process.cwd(), 'package.json');
const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf-8'));

const healthModule: FastifyPluginAsync = async (fastify) => {
  // GET /health
  fastify.get('/', async () => {
    const { getDatabaseInfo } = await import('@core/database/pool');
    const dbInfo = await getDatabaseInfo();
    
    // Obter versão do mapa canônico de permissões
    const canonicalPermissionsVersion = 'v1.3'; // Sincronizado com permission-keys.ts
    
    // Verificar status dos módulos críticos
    const modules: Record<string, 'ok' | 'error'> = {};
    
    try {
      // Marketplace
      const { marketplaceService } = await import('@modules/marketplace/marketplace.service');
      marketplaceService.getHealth();
      modules.marketplace = 'ok';
    } catch (err) {
      modules.marketplace = 'error';
    }
    
    try {
      // Social (verificar se registry está inicializado)
      const { socialPortsRegistry } = await import('@core/social/ports-registry');
      if (socialPortsRegistry) {
        modules.social = 'ok';
      } else {
        modules.social = 'error';
      }
    } catch (err) {
      modules.social = 'error';
    }
    
    try {
      // Bank (verificar se registry está inicializado)
      const { bankPortsRegistry } = await import('@core/bank/ports-registry');
      if (bankPortsRegistry) {
        modules.bank = 'ok';
      } else {
        modules.bank = 'error';
      }
    } catch (err) {
      modules.bank = 'error';
    }
    
    // 🔴 INSTRUMENTAÇÃO: Retornar informações de runtime para diagnóstico
    const serverAddress = fastify.server.address();
    const actualPort = typeof serverAddress === 'string' 
      ? null 
      : serverAddress?.port || null;
    
    return {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      version: packageJson.version || '1.0.0',
      canonical_permissions_version: canonicalPermissionsVersion,
      modules,
      runtime: {
        pid: process.pid,
        nodeVersion: process.version,
        platform: process.platform,
        arch: process.arch,
        port: actualPort,
        env: process.env.NODE_ENV || 'development',
      },
      database: dbInfo ? {
        connected: true,
        host: dbInfo.host,
        port: dbInfo.port,
        database: dbInfo.database,
        schema: dbInfo.currentSchema,
        user: dbInfo.currentUser,
        connectionCount: dbInfo.connectionCount,
      } : {
        connected: false,
      },
    };
  });

  // GET /health/ready
  fastify.get('/ready', async (_req, reply) => {
    try {
      // Verifica conexão com banco
      await pool.query('SELECT 1');
      return { status: 'ready', database: 'connected' };
    } catch {
      return reply.status(503).send({
        status: 'not ready',
        database: 'disconnected',
      });
    }
  });

  // GET /health/live
  fastify.get('/live', async () => {
    return { status: 'live' };
  });
};

export { healthModule };
